GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO "$QGIS_DB_USER";

        -- Set default privileges for future tables created by the main user
        ALTER DEFAULT PRIVILEGES FOR ROLE "$POSTGRES_USER" IN SCHEMA public
            GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO "$QGIS_DB_USER";
        ALTER DEFAULT PRIVILEGES FOR ROLE "$POSTGRES_USER" IN SCHEMA public
            GRANT USAGE, SELECT ON SEQUENCES TO "$QGIS_DB_USER";

        -- Revoke access on model and route permissions (these tables are created by
        -- Django migrations and do not exist yet on a fresh install, so only revoke
        -- when they are present)
        DO \$\$
        BEGIN
            IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema='public' AND table_name='model_permission') THEN
                REVOKE ALL ON model_permission FROM "$QGIS_DB_USER";
            END IF;
            IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema='public' AND table_name='route_permission') THEN
                REVOKE ALL ON route_permission FROM "$QGIS_DB_USER";
            END IF;
        END
        \$\$;
